      SUBROUTINE MVTODRCC     CALCULATES DISPLACEMENTS AND ROTATION ANGLE FOR MISALIGNMENTSCC     LIST OF COMMON BLOCKSC      INCLUDE 'ELM8B.CIN'      INCLUDE 'ELM8K.CIN'CC     LOCAL VARIABLESC      EQUIVALENCE  (RX,VROT(1)), (RY,VROT(2)), (RZ,VROT(3))CC------------------------------------------------------------      DO 10 J = 1, 3      VDIS(J) = VM(2*J-1)   10 VROT(J) = VM(2*J)      THMIS = SQRT(RX**2 + RY**2 + RZ**2)      SNM = SIN(THMIS)      CSM = COS(THMIS)      ZNM = SNM**2/(1.0 + CSM)      IF (THMIS .NE. 0) THEN        RX = RX/THMIS        RY = RY/THMIS        RZ = RZ/THMIS      ENDIF      RETURN      END